begin;
create temp table lp_checks(label text);grant select,insert on lp_checks to anon,authenticated;
create function pg_temp.lp_assert(ok boolean,label text) returns void language plpgsql as $$ begin
 if ok is distinct from true then raise exception 'FAIL %',label;end if;insert into lp_checks values(label);
end $$;
create function pg_temp.lp_denied(command text,label text) returns void language plpgsql as $$ begin
 begin execute command;exception when others then if sqlstate in ('42501','23514') then perform pg_temp.lp_assert(true,label);return;end if;raise;end;
 raise exception 'Expected denial %',label;
end $$;
select set_config('lp.admin',(select id::text from public.profiles where role='ADMIN' and status='ACTIVE' limit 1),true),
 set_config('lp.one',gen_random_uuid()::text,true),set_config('lp.two',gen_random_uuid()::text,true),set_config('lp.locked',gen_random_uuid()::text,true),
 set_config('lp.bank','learning-'||gen_random_uuid(),true),set_config('lp.shared',gen_random_uuid()::text,true),set_config('lp.past',gen_random_uuid()::text,true);
insert into auth.users(id,email,raw_user_meta_data) select current_setting('lp.'||v)::uuid,current_setting('lp.'||v)||'@example.invalid','{"full_name":"Learning rollback"}' from unnest(array['one','two','locked']) v;
insert into public.question_banks(id,name,description,status,specialty_id) values(current_setting('lp.bank'),'[TEST] Nursing Colloquium','Catalog rollback','active',(select id from public.specialties where slug='nursing'));
insert into public.question_sections(id,question_bank_id,title,description,display_order) values(current_setting('lp.bank')||'-case',current_setting('lp.bank'),'Original case','Original preserved context',1);
insert into public.bank_questions(id,question_bank_id,text,status,options,section_id,display_order)
 select current_setting('lp.bank')||'-q'||i,current_setting('lp.bank'),'Original question '||i,'active','[{"id":"a","text":"First"},{"id":"b","text":"Second"}]',current_setting('lp.bank')||'-case',i from generate_series(1,40)i;
insert into private.question_solutions select current_setting('lp.bank')||'-q'||i,'a' from generate_series(1,40)i;
insert into public.user_bank_access(user_id,question_bank_id,status,granted_by) select current_setting('lp.'||v)::uuid,current_setting('lp.bank'),'ACTIVE',current_setting('lp.admin')::uuid from unnest(array['one','two'])v;
select pg_temp.lp_assert((select count(*)=3 from public.specialties where slug in ('nursing','medical','dentistry')),'three independent configured specialties');
set local role anon;
select pg_temp.lp_assert(public.learning_catalog()::text like '%'||current_setting('lp.bank')||'%','anon sees published material summary');
select pg_temp.lp_assert(public.learning_catalog()::text !~ 'options|correct_option_id|answer_key|storage_path','public catalog excludes protected content');
select pg_temp.lp_denied('select public.admin_shared_exams(current_setting(''lp.bank''))','anon denies admin definitions');
reset role;set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.admin'),'role','authenticated')::text,true);
select public.assign_bank_specialty(current_setting('lp.bank'),null);
select pg_temp.lp_assert((select specialty_id is null from public.question_banks where id=current_setting('lp.bank')),'admin can unassign metadata only');
select public.assign_bank_specialty(current_setting('lp.bank'),(select id from public.specialties where slug='nursing'));
select pg_temp.lp_assert(public.learning_catalog()::text like '%'||current_setting('lp.bank')||'%','admin assignment reflected in catalog');
select public.save_specialty(jsonb_build_object('id',gen_random_uuid(),'slug','rollback-hidden','name','Hidden configuration','description','','icon','other','published',false,'displayOrder',50));
select pg_temp.lp_assert(public.learning_catalog()::text not like '%rollback-hidden%','hidden specialty not publicly advertised');
select set_config('lp.generate',jsonb_build_object('id',current_setting('lp.shared'),'bankId',current_setting('lp.bank'),'title','[TEST] Shared A','count',35,'timeLimitMinutes',null)::text,true);
select pg_temp.lp_assert(public.generate_shared_exam(current_setting('lp.generate')::jsonb)::text=current_setting('lp.shared'),'admin generates draft');
select pg_temp.lp_assert(public.generate_shared_exam(current_setting('lp.generate')::jsonb)::text=current_setting('lp.shared'),'generation idempotent');
select pg_temp.lp_assert(public.admin_shared_exams(current_setting('lp.bank'))->0->>'questionCount'='35','shared draft exceeds personal cap');
select set_config('lp.save',jsonb_build_object('id',current_setting('lp.shared'),'title','[TEST] Shared A','status','DRAFT','timeLimitMinutes',null,'questionIds',
 (select jsonb_agg(q->>'questionId' order by (q->>'position')::integer desc) from jsonb_array_elements(public.admin_shared_exams(current_setting('lp.bank'))->0->'questions')q))::text,true);
select public.save_shared_exam(current_setting('lp.save')::jsonb);
select pg_temp.lp_assert(public.admin_shared_exams(current_setting('lp.bank'))->0->'questions'->0->>'questionId'=current_setting('lp.save')::jsonb->'questionIds'->>0,'admin reorder persisted');
select pg_temp.lp_denied('select public.save_shared_exam(jsonb_set(current_setting(''lp.save'')::jsonb,''{questionIds}'',''[]''))','cannot change generated set');
select public.save_shared_exam(jsonb_set(current_setting('lp.save')::jsonb,'{status}','"PUBLISHED"'));
select pg_temp.lp_denied('select public.save_shared_exam(jsonb_set(jsonb_set(current_setting(''lp.save'')::jsonb,''{title}'',''"Changed"''),''{status}'',''"PUBLISHED"''))','published definition immutable');
select set_config('lp.pastPayload',jsonb_build_object('id',current_setting('lp.past'),'bankId',current_setting('lp.bank'),'sourceId',null,'title','[TEST] Exam 2023','year',2023,'session','Original','timeLimitMinutes',null,'provenance','Rollback historical fixture','status','PUBLISHED',
 'questions',(select jsonb_agg(jsonb_build_object('id',b.id,'reuseQuestionId',b.id,'sourceNumber',i::text,'text',b.text,'options',b.options,'correctOptionId','a','verified',true,'includeInBank',true,'caseId',null,'caseTitle','','caseDescription','','warnings','[]'::jsonb) order by i)
 from unnest(array[2,1,3]) with ordinality t(n,i) join public.bank_questions b on b.id=current_setting('lp.bank')||'-q'||n))::text,true);
select public.save_past_exam(current_setting('lp.pastPayload')::jsonb);
reset role;
update public.bank_questions set text='Later bank revision' where question_bank_id=current_setting('lp.bank');
update private.question_solutions set correct_option_id='b' where question_id like current_setting('lp.bank')||'-q%';
set local role authenticated;
select set_config('lp.sharedConfig',jsonb_build_object('bankId',current_setting('lp.bank'),'source','SHARED','sourceId',current_setting('lp.shared'),'mode','EXAM','count',30,'timeLimitMinutes',null)::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.locked'),'role','authenticated')::text,true);
select pg_temp.lp_denied('select public.start_learning_exam(current_setting(''lp.sharedConfig'')::jsonb)','locked bank shared start denied');
select pg_temp.lp_assert((select count(*)=0 from public.shared_exams),'locked bank shared metadata RLS');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.one'),'role','authenticated')::text,true);
select pg_temp.lp_denied('select public.assign_bank_specialty(current_setting(''lp.bank''),null)','student cannot assign materials');
select pg_temp.lp_denied('select public.save_specialty(''{}''::jsonb)','student cannot edit specialties');
select pg_temp.lp_denied('update public.shared_exams set title=''Bypass'' where id=current_setting(''lp.shared'')::uuid','student cannot directly mutate definitions');
reset role;
update public.profiles set role='TEACHER',activation_start=current_date,activation_months=1,expiration_date=current_date+interval '1 month' where id=current_setting('lp.one')::uuid;
set local role authenticated;
select pg_temp.lp_denied('select public.generate_shared_exam(current_setting(''lp.generate'')::jsonb)','teacher cannot generate shared definitions');
reset role;
update public.profiles set role='STUDENT' where id=current_setting('lp.one')::uuid;
set local role authenticated;
select pg_temp.lp_denied('select public.generate_shared_exam(current_setting(''lp.generate'')::jsonb)','student cannot generate');
select pg_temp.lp_denied('select public.admin_shared_exams(current_setting(''lp.bank''))','student cannot see admin snapshots');
select pg_temp.lp_denied('select * from private.shared_exam_questions','student cannot read private keys');
select set_config('lp.a',public.start_learning_exam(current_setting('lp.sharedConfig')::jsonb)::text,true);
select pg_temp.lp_assert(public.start_learning_exam(current_setting('lp.sharedConfig')::jsonb)::text=current_setting('lp.a'),'shared resume idempotent');
select set_config('lp.aData',public.exam_data(current_setting('lp.a')::uuid)::text,true);
select pg_temp.lp_assert(current_setting('lp.aData')::jsonb->>'totalQuestions'='35','shared attempt uses whole fixed set');
select pg_temp.lp_assert(current_setting('lp.aData')::jsonb->'questions'->0->>'text' like 'Original question %','shared text frozen from generation');
select pg_temp.lp_assert(current_setting('lp.aData')::jsonb->'questions'->0->>'caseDescription'='Original preserved context','shared clinical context preserved');
select pg_temp.lp_assert(current_setting('lp.aData') !~ 'correctOptionId|outcome|correct_option_id','active shared keys absent');
select pg_temp.lp_denied('select public.check_practice_answer(current_setting(''lp.a'')::uuid,current_setting(''lp.aData'')::jsonb->''questions''->0->>''id'')','shared exam feedback blocked');
select public.save_exam_answer(current_setting('lp.a')::uuid,current_setting('lp.aData')::jsonb->'questions'->0->>'id','a');
select public.submit_exam(current_setting('lp.a')::uuid);
select pg_temp.lp_assert(public.exam_data(current_setting('lp.a')::uuid)->'result'->>'correct'='1','shared grading uses frozen original key');
select pg_temp.lp_assert(public.submit_exam(current_setting('lp.a')::uuid)::text=current_setting('lp.a'),'shared submit idempotent');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.two'),'role','authenticated')::text,true);
select pg_temp.lp_denied('select public.exam_data(current_setting(''lp.a'')::uuid)','shared attempt student isolation');
select set_config('lp.b',public.start_learning_exam(current_setting('lp.sharedConfig')::jsonb)::text,true);
select pg_temp.lp_assert(current_setting('lp.a')<>current_setting('lp.b'),'two students independent shared attempts');
select pg_temp.lp_assert((select jsonb_agg(q->>'id' order by (q->>'order')::int) from jsonb_array_elements(public.exam_data(current_setting('lp.b')::uuid)->'questions')q)=
 (select jsonb_agg(q->>'id' order by (q->>'order')::int) from jsonb_array_elements(current_setting('lp.aData')::jsonb->'questions')q),'two students exact same shared set and order');
select pg_temp.lp_assert(public.exam_data(current_setting('lp.b')::uuid)->'questions'->0->>'selectedOptionId' is null,'shared answers not copied between students');
select public.save_exam_answer(current_setting('lp.b')::uuid,public.exam_data(current_setting('lp.b')::uuid)->'questions'->0->>'id','b');
select public.submit_exam(current_setting('lp.b')::uuid);
select pg_temp.lp_assert(public.exam_data(current_setting('lp.b')::uuid)->'result'->>'correct'='0','shared scores independent');
select set_config('lp.pastConfig',jsonb_build_object('bankId',current_setting('lp.bank'),'source','PAST','sourceId',current_setting('lp.past'),'mode','EXAM','count',30,'timeLimitMinutes',null)::text,true);
select set_config('lp.pb',public.start_learning_exam(current_setting('lp.pastConfig')::jsonb)::text,true);
select public.submit_exam(current_setting('lp.pb')::uuid);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.one'),'role','authenticated')::text,true);
select set_config('lp.pa',public.start_learning_exam(current_setting('lp.pastConfig')::jsonb)::text,true);
select pg_temp.lp_assert(public.exam_data(current_setting('lp.pa')::uuid)->'questions'->0->>'id'=current_setting('lp.bank')||'-q2','historical original first question retained');
select pg_temp.lp_assert(public.exam_data(current_setting('lp.pa')::uuid)->'questions'->0->>'text'='Original question 2','historical content snapshot preserved after bank edits');
reset role;
select pg_temp.lp_assert((select jsonb_agg(question_id order by display_order) from public.question_attempt_questions where attempt_id=current_setting('lp.pa')::uuid)=
 (select jsonb_agg(question_id order by display_order) from public.question_attempt_questions where attempt_id=current_setting('lp.pb')::uuid),'same historical set and order');
set local role authenticated;
select public.submit_exam(current_setting('lp.pa')::uuid);
select set_config('lp.randomConfig',jsonb_build_object('bankId',current_setting('lp.bank'),'source','RANDOM','sourceId',null,'mode','EXAM','count',30,'timeLimitMinutes',null)::text,true);
select set_config('lp.ra',public.start_learning_exam(current_setting('lp.randomConfig')::jsonb)::text,true);
select pg_temp.lp_assert(jsonb_array_length(public.exam_data(current_setting('lp.ra')::uuid)->'questions')=30,'personal random cap retained');
select pg_temp.lp_assert((select count(distinct q->>'id')=30 from jsonb_array_elements(public.exam_data(current_setting('lp.ra')::uuid)->'questions')q),'personal questions unique');
select pg_temp.lp_assert(public.start_learning_exam(current_setting('lp.randomConfig')::jsonb)::text=current_setting('lp.ra'),'personal refresh frozen');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.two'),'role','authenticated')::text,true);
select set_config('lp.rb',public.start_learning_exam(current_setting('lp.randomConfig')::jsonb)::text,true);
select pg_temp.lp_assert(current_setting('lp.ra')<>current_setting('lp.rb'),'personal students independent generated attempts');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.admin'),'role','authenticated')::text,true);
select pg_temp.lp_denied('select public.start_learning_exam(current_setting(''lp.sharedConfig'')::jsonb)','admin view-as cannot start shared');
select public.save_shared_exam(jsonb_set(current_setting('lp.save')::jsonb,'{status}','"ARCHIVED"'));
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.one'),'role','authenticated')::text,true);
select public.submit_exam(current_setting('lp.ra')::uuid);
select pg_temp.lp_denied('select public.start_learning_exam(current_setting(''lp.sharedConfig'')::jsonb)','archived definition cannot start new attempt');
select pg_temp.lp_assert(public.exam_data(current_setting('lp.a')::uuid)->>'status'='COMPLETED','archived definition retains completed results');
select pg_temp.lp_assert((select count(*)=40 from public.bank_questions where question_bank_id=current_setting('lp.bank')),'generation does not duplicate bank questions');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('lp.admin'),'role','authenticated')::text,true);
select public.generate_shared_exam(jsonb_build_object('id',gen_random_uuid(),'bankId',current_setting('lp.bank'),'title','Rollback pagination '||n,'count',1,'timeLimitMinutes',null)) from generate_series(1,6)n;
select pg_temp.lp_assert(jsonb_array_length(public.admin_shared_exams(current_setting('lp.bank'),0))=5,'admin definition page is bounded');
select pg_temp.lp_assert(jsonb_array_length(public.admin_shared_exams(current_setting('lp.bank'),1))=2,'older definitions remain available on next page');
select pg_temp.lp_denied('select public.admin_shared_exams(current_setting(''lp.bank''),-1)','invalid page rejected');
select count(*) passed_checks,array_agg(label) checks from lp_checks;
rollback;
